import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { countries } from '../data/locations';
import {
  validateName,
  validateUsername,
  validateEmail,
  validatePassword,
  validatePhone,
  validatePan,
  validateAadhar
} from '../utils/validation';
import './RegistrationForm.css';

const RegistrationForm = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    username: '',
    email: '',
    password: '',
    countryCode: '+91',
    phoneNumber: '',
    country: '',
    city: '',
    panNumber: '',
    aadharNumber: ''
  });

  const [errors, setErrors] = useState({});
  const [showPassword, setShowPassword] = useState(false);
  const [availableCities, setAvailableCities] = useState([]);
  const [isFormValid, setIsFormValid] = useState(false);
  const [activeCard, setActiveCard] = useState('basic');

  const cards = {
    basic: {
      title: 'Basic Details',
      icon: '📝',
      fields: ['firstName', 'lastName', 'username']
    },
    contact: {
      title: 'Contact Information',
      icon: '📞',
      fields: ['email', 'password', 'phoneNumber', 'countryCode']
    },
    location: {
      title: 'Location Details',
      icon: '🌍',
      fields: ['country', 'city']
    },
    identity: {
      title: 'Identity Verification',
      icon: '🆔',
      fields: ['panNumber', 'aadharNumber']
    }
  };

  useEffect(() => {
    if (formData.country) {
      const selectedCountry = countries.find(c => c.code === formData.country);
      setAvailableCities(selectedCountry ? selectedCountry.cities : []);
      if (!selectedCountry?.cities.includes(formData.city)) {
        setFormData(prev => ({ ...prev, city: '' }));
      }
    }
  }, [formData.country]);

  useEffect(() => {
    validateForm();
  }, [formData]);

  const getValidationMessage = (field) => {
    switch(field) {
      case 'firstName':
        return 'Start with a capital letter, minimum 2 characters';
      case 'lastName':
        return 'Start with a capital letter, minimum 2 characters';
      case 'username':
        return 'Use letters, numbers, and underscores only';
      case 'email':
        return 'Enter a valid email address (e.g., name@domain.com)';
      case 'password':
        return 'Include uppercase, lowercase, number, and special character';
      case 'phoneNumber':
        return 'Enter 10 digits without spaces';
      case 'country':
        return 'Select your current country';
      case 'city':
        return 'Select your current city';
      case 'panNumber':
        return 'Format: ABCDE1234F';
      case 'aadharNumber':
        return '12 digits without spaces';
      default:
        return '';
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!validateName(formData.firstName)) {
      newErrors.firstName = getValidationMessage('firstName');
    }
    if (!validateName(formData.lastName)) {
      newErrors.lastName = getValidationMessage('lastName');
    }
    if (!validateUsername(formData.username)) {
      newErrors.username = getValidationMessage('username');
    }
    if (!validateEmail(formData.email)) {
      newErrors.email = getValidationMessage('email');
    }
    if (!validatePassword(formData.password)) {
      newErrors.password = getValidationMessage('password');
    }
    if (!validatePhone(formData.phoneNumber)) {
      newErrors.phoneNumber = getValidationMessage('phoneNumber');
    }
    if (!formData.country) {
      newErrors.country = getValidationMessage('country');
    }
    if (!formData.city) {
      newErrors.city = getValidationMessage('city');
    }
    if (!validatePan(formData.panNumber)) {
      newErrors.panNumber = getValidationMessage('panNumber');
    }
    if (!validateAadhar(formData.aadharNumber)) {
      newErrors.aadharNumber = getValidationMessage('aadharNumber');
    }

    setErrors(newErrors);
    setIsFormValid(Object.keys(newErrors).length === 0);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (isFormValid) {
      navigate('/success', { state: { formData } });
    }
  };

  const renderField = (fieldName) => {
    switch(fieldName) {
      case 'firstName':
      case 'lastName':
        return (
          <input
            type="text"
            name={fieldName}
            value={formData[fieldName]}
            onChange={handleChange}
            className={errors[fieldName] ? 'error' : ''}
            placeholder={`Enter your ${fieldName.replace('Name', ' name')}`}
          />
        );
      case 'username':
        return (
          <input
            type="text"
            name="username"
            value={formData.username}
            onChange={handleChange}
            className={errors.username ? 'error' : ''}
            placeholder="Choose a unique username"
          />
        );
      case 'email':
        return (
          <input
            type="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            className={errors.email ? 'error' : ''}
            placeholder="your.email@example.com"
          />
        );
      case 'password':
        return (
          <div className="password-field">
            <input
              type={showPassword ? 'text' : 'password'}
              name="password"
              value={formData.password}
              onChange={handleChange}
              className={errors.password ? 'error' : ''}
              placeholder="Create a strong password"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="visibility-toggle"
            >
              {showPassword ? '🔐' : '👁️'}
            </button>
          </div>
        );
      case 'phoneNumber':
        return (
          <div className="phone-field">
            <select
              name="countryCode"
              value={formData.countryCode}
              onChange={handleChange}
              className="country-code"
            >
              <option value="+91">🇮🇳 +91</option>
              <option value="+1">🇺🇸 +1</option>
              <option value="+44">🇬🇧 +44</option>
              <option value="+61">🇦🇺 +61</option>
            </select>
            <input
              type="tel"
              name="phoneNumber"
              value={formData.phoneNumber}
              onChange={handleChange}
              className={errors.phoneNumber ? 'error' : ''}
              placeholder="Enter mobile number"
            />
          </div>
        );
      case 'country':
        return (
          <select
            name="country"
            value={formData.country}
            onChange={handleChange}
            className={errors.country ? 'error' : ''}
          >
            <option value="">Select your country</option>
            {countries.map(country => (
              <option key={country.code} value={country.code}>
                {country.name}
              </option>
            ))}
          </select>
        );
      case 'city':
        return (
          <select
            name="city"
            value={formData.city}
            onChange={handleChange}
            className={errors.city ? 'error' : ''}
            disabled={!formData.country}
          >
            <option value="">Select your city</option>
            {availableCities.map(city => (
              <option key={city} value={city}>
                {city}
              </option>
            ))}
          </select>
        );
      case 'panNumber':
        return (
          <input
            type="text"
            name="panNumber"
            value={formData.panNumber}
            onChange={handleChange}
            className={errors.panNumber ? 'error' : ''}
            placeholder="ABCDE1234F"
          />
        );
      case 'aadharNumber':
        return (
          <input
            type="text"
            name="aadharNumber"
            value={formData.aadharNumber}
            onChange={handleChange}
            className={errors.aadharNumber ? 'error' : ''}
            placeholder="123456789012"
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="registration-container">
      <h1 className="form-title">Create Account</h1>

      <div className="card-navigation">
        {Object.entries(cards).map(([key, card]) => (
          <button
            key={key}
            className={`nav-card ${activeCard === key ? 'active' : ''}`}
            onClick={() => setActiveCard(key)}
          >
            <span className="card-icon">{card.icon}</span>
            {card.title}
          </button>
        ))}
      </div>

      <form onSubmit={handleSubmit} className="registration-form">
        <div className="form-cards">
          {Object.entries(cards).map(([key, card]) => (
            <div
              key={key}
              className={`form-card ${activeCard === key ? 'active' : ''}`}
            >
              <div className="card-header">
                <span className="card-icon">{card.icon}</span>
                <h2>{card.title}</h2>
              </div>
              <div className="card-content">
                {card.fields.map(field => (
                  <div key={field} className="field-group">
                    <label>
                      {field.charAt(0).toUpperCase() + field.slice(1).replace(/([A-Z])/g, ' $1')}
                      <span className="required">*</span>
                    </label>
                    {renderField(field)}
                    {errors[field] && (
                      <span className="error-message">
                        {errors[field]}
                      </span>
                    )}
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>

        <div className="form-actions">
          <button
            type="submit"
            className={`submit-button ${isFormValid ? 'valid' : ''}`}
            disabled={!isFormValid}
          >
            {isFormValid ? 'Complete Registration ✨' : 'Please Fill All Fields'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default RegistrationForm;
